43	/**
44	 * Added at the very end of every premium, after all percentage modifiers, so
45	 * no surcharge or discount is ever computed on top of it.
46	 */
47	const PROCESSING_FEE = 5;
48	
49	/**
50	 * Rates are kept as exact numerator/denominator fractions rather than float
51	 * multipliers (10 / 100, never 1.1) so intermediate amounts stay exact and
52	 * only the final premium is rounded.
53	 */
54	const percent = (amount: number, rate: number): number => (amount * rate) / 100;
55	
56	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
57	const CURSE_SURCHARGE_PERCENT = 50;
58	
59	/**
60	 * Everything the pricing rules need to know about an item type lives here, so
61	 * that "what is a rune?" has a single answer. Components are the small parts
62	 * (runes, moonstones) that can be bought as a building block; main items
63	 * (swords, amulets, ...) never form a block.
64	 */
65	const ITEM_TYPES: Record<string, { basePremium: number; isComponent: boolean }> =
66	  {
67	    sword: { basePremium: 100, isComponent: false },
68	    amulet: { basePremium: 60, isComponent: false },
69	    staff: { basePremium: 80, isComponent: false },
70	    potion: { basePremium: 40, isComponent: false },
71	    rune: { basePremium: 25, isComponent: true },
72	    moonstone: { basePremium: 25, isComponent: true },
73	  };
74	
75	/** A building block of 3 alike components is offered at this base premium. */
76	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
77	const COMPONENT_BLOCK_SIZE = 3;
78	
79	/** Tallies how many items of each type a policy covers, e.g. [["rune", 3]]. */
80	const countByType = (items: Item[]): [string, number][] => {
81	  const counts = new Map<string, number>();
82	  for (const item of items) {
83	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
84	  }
85	  return [...counts];
86	};
87	
88	/**
89	 * Prices every item of one type together, because exactly 3 alike components
90	 * form a block charged as one. "Alike" means the same type, and the block does
91	 * not repeat: 4 or 7 runes are each priced per item.
92	 */
93	const basePremiumForType = (type: string, count: number): number => {
94	  const { basePremium, isComponent } = ITEM_TYPES[type];
95	  return isComponent && count === COMPONENT_BLOCK_SIZE
96	    ? COMPONENT_BLOCK_BASE_PREMIUM
97	    : count * basePremium;
98	};
99	
100	const sumOfBasePremiums = (items: Item[]): number =>
101	  countByType(items).reduce(
102	    (sum, [type, count]) => sum + basePremiumForType(type, count),
103	    0,
104	  );
105	
106	/**
107	 * Item-specific modifiers are charged on the affected item's own base premium,
108	 * not on the policy total.
109	 */
110	const sumOfItemSurcharges = (items: Item[]): number =>
111	  items.reduce(
112	    (sum, item) =>
113	      item.cursed
114	        ? sum + percent(ITEM_TYPES[item.type].basePremium, CURSE_SURCHARGE_PERCENT)
115	        : sum,
116	    0,
117	  );
118	
119	export const runScenario = (scenario: Scenario): ScenarioResult => {
120	  const quote = scenario.steps[0] as QuoteStep;
121	  const basePremium = sumOfBasePremiums(quote.items);
122	  const premiumAfterPercentageModifiers =
123	    basePremium +
124	    sumOfItemSurcharges(quote.items) +
125	    percent(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT);
126	  return {
127	    results: [
128	      { premium: Math.ceil(premiumAfterPercentageModifiers + PROCESSING_FEE) },
129	    ],
130	  };
131	};
